// Split all files into individual items for batch processing
const folderName = $node["Google Drive Trigger"].json.name;
const folderId = $node["Google Drive Trigger"].json.id;
const response = $input.first().json;

console.log('🔍 BATCH PROCESSING SETUP:');
console.log('Response:', JSON.stringify(response, null, 2));

const files = (response && response.files) ? response.files : [];

if (!files || !Array.isArray(files) || files.length === 0) {
  console.log('❌ No PDF files found');
  return [{
    json: {
      error: 'No PDF files found',
      folder_name: folderName,
      folder_id: folderId
    }
  }];
}

// Extract company name
let companyName = folderName || 'Unknown_Company';
companyName = companyName
  .replace(/^(new folder|folder|untitled|document)$/i, 'Unknown_Company')
  .replace(/[_-]+/g, ' ')
  .replace(/\s+/g, ' ')
  .trim();

if (companyName.length < 2) {
  companyName = 'Unknown_Company';
}

const sessionId = `batch_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

console.log(`🚀 BATCH PROCESSING: ${files.length} files`);
console.log(`📁 Folder: ${folderName}`);
console.log(`🏢 Company: ${companyName}`);

// Return each file as a separate item for parallel processing
return files.map((file, index) => ({
  json: {
    session_id: sessionId,
    company_name: companyName,
    folder_id: folderId,
    folder_name: folderName,
    total_files: files.length,
    file_index: index,
    file_id: file.id,
    file_name: file.name,
    file_size: file.size,
    file_mime_type: file.mimeType,
    processing_mode: 'batch'
  }
}));

// Process extracted text and create chunks for each file
const extractedData = $input.first().json;
const fileInfo = $node["Split Files for Batch Processing"].json;

console.log(`📄 Processing: ${fileInfo.file_name} (${fileInfo.file_index + 1}/${fileInfo.total_files})`);

// Get extracted text
let fullText = '';
if (extractedData && extractedData.data) {
  fullText = extractedData.data;
} else if (typeof extractedData === 'string') {
  fullText = extractedData;
}

if (!fullText || fullText.length < 100) {
  console.error(`❌ Text extraction failed for ${fileInfo.file_name}`);
  return [{
    json: {
      ...fileInfo,
      error: 'Text extraction failed',
      processing_status: 'failed'
    }
  }];
}

// Estimate pages
const estimatedPages = Math.max(1, Math.ceil(fullText.length / 2000));

console.log(`📊 Extracted ${fullText.length} characters (~${estimatedPages} pages) from ${fileInfo.file_name}`);

// Create chunks
const chunkSize = 1000;
const overlap = 200;
const chunks = [];

for (let i = 0; i < fullText.length; i += (chunkSize - overlap)) {
  const chunk = fullText.substring(i, i + chunkSize);
  if (chunk.trim().length > 50) {
    chunks.push({
      content: chunk.trim(),
      metadata: {
        session_id: fileInfo.session_id,
        file_name: fileInfo.file_name,
        company_name: fileInfo.company_name,
        file_id: fileInfo.file_id,
        folder_id: fileInfo.folder_id,
        chunk_index: chunks.length,
        total_chunks_this_file: Math.ceil(fullText.length / (chunkSize - overlap)),
        file_index: fileInfo.file_index,
        total_files: fileInfo.total_files,
        actual_pages: estimatedPages,
        extracted_at: new Date().toISOString(),
        processing_mode: 'batch'
      }
    });
  }
}

console.log(`📦 Created ${chunks.length} chunks for ${fileInfo.file_name}`);

// Return all chunks for this file
return chunks.map(chunk => ({
  json: {
    pageContent: chunk.content,
    metadata: chunk.metadata,
    file_info: {
      ...fileInfo,
      chunks_created: chunks.length,
      pages_estimated: estimatedPages,
      characters_extracted: fullText.length,
      processing_status: 'completed'
    }
  }
}));

// Aggregate results and create final summary
const allInputs = $input.all();

if (!allInputs || allInputs.length === 0) {
  console.log('❌ No results to aggregate');
  return {
    json: {
      error: 'No processing results received',
      status: 'failed'
    }
  };
}

// Group by files and calculate totals
const fileMap = new Map();
let totalChunks = 0;
let totalPages = 0;
const sessionInfo = allInputs[0].json.file_info;

allInputs.forEach(input => {
  if (input.json && input.json.file_info) {
    const fileInfo = input.json.file_info;
    const fileName = fileInfo.file_name;

    if (!fileMap.has(fileName)) {
      fileMap.set(fileName, {
        file_name: fileName,
        file_id: fileInfo.file_id,
        chunks: fileInfo.chunks_created || 0,
        pages: fileInfo.pages_estimated || 0,
        characters: fileInfo.characters_extracted || 0,
        status: fileInfo.processing_status || 'unknown'
      });

      totalChunks += fileInfo.chunks_created || 0;
      totalPages += fileInfo.pages_estimated || 0;
    }
  }
});

const processedFiles = Array.from(fileMap.values());
const successfulFiles = processedFiles.filter(f => f.status === 'completed');
const failedFiles = processedFiles.filter(f => f.status === 'failed');

const successRate = processedFiles.length > 0 ? (successfulFiles.length / processedFiles.length * 100).toFixed(2) : 0;

console.log('🎉 BATCH PROCESSING COMPLETE!');
console.log('═'.repeat(50));
console.log(`🏢 Company: ${sessionInfo.company_name}`);
console.log(`📁 Folder: ${sessionInfo.folder_name}`);
console.log(`📄 Files Processed: ${successfulFiles.length}/${processedFiles.length}`);
console.log(`📦 Total Chunks: ${totalChunks}`);
console.log(`📑 Total Pages: ${totalPages}`);
console.log(`✅ Success Rate: ${successRate}%`);
console.log(`💾 Vector Store: Pinecone index 'n8n'`);
console.log(`🤖 Embedding Model: mxbai-embed-large (1024 dimensions)`);
console.log('═'.repeat(50));

return {
  json: {
    processing_complete: true,
    processing_mode: 'batch',
    session_id: sessionInfo.session_id,
    company_name: sessionInfo.company_name,
    folder_name: sessionInfo.folder_name,
    summary: {
      total_files: processedFiles.length,
      successful_files: successfulFiles.length,
      failed_files: failedFiles.length,
      success_rate: `${successRate}%`,
      total_chunks: totalChunks,
      total_pages: totalPages
    },
    processed_files: processedFiles,
    failed_files: failedFiles.map(f => f.file_name),
    technical_details: {
      pinecone_index: 'n8n',
      embedding_model: 'mxbai-embed-large',
      embedding_dimensions: 1024,
      chunk_size: 1000,
      chunk_overlap: 200
    },
    ready_for_rag_queries: successfulFiles.length > 0,
    completed_at: new Date().toISOString(),
    status_message: `🎉 Batch processing complete! ${successfulFiles.length}/${processedFiles.length} files successfully processed.`
  }
};
